 private final BroadcastReceiver scanReceiver=new BroadcastReceiver(){public void onReceive(Context context,Intent intent){if(resumed&&"android.intent.action.SCANRESULT".equals(intent.getAction())){String code=intent.getStringExtra("value");if(code!=null&&!code.trim().isEmpty())receive(code.trim(),"broadcast");}}};
 private static final int BG=Color.rgb(11,18,30),PANEL=Color.rgb(23,39,60),CYAN=Color.rgb(41,218,224),TEXT=Color.rgb(237,245,255);
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new LocalStore(this);store.put("active_document","");api=new WarehouseApi(new SecurePrefs(this));sync=new SyncEngine(store,api);automaticSync=new CoalescingTask(network,this::syncAutomatically);updates=new AppUpdates(this,store);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);screen();UpdateJob.schedule(this,true);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},7302);start();network.scheduleWithFixedDelay(()->{if(!resumed)return;if(ready)try{sync.sync();sync.catalog(false);connection="Связь с сервером есть";}catch(Exception e){connection=explain(e);}try{String update=updates.check(false);if(!update.isEmpty())connection=update;}catch(Exception updateError){store.put("update_check_error",updateError.getMessage()==null?"network_error":updateError.getMessage());connection="Ошибка обновления: "+updateError.getMessage();}DeviceStatus.send(this,store,api);ui.post(()->{refresh();offerUpdate();});},2,2,TimeUnit.SECONDS);}
 private void syncAutomatically(){try{sync.sync();connection="Связь с сервером есть";}catch(Exception e){connection=explain(e);}if(!automaticSync.isClosed())ui.post(()->{if(!automaticSync.isClosed())refresh();});}
 private String explain(Exception e){if(e instanceof WarehouseApi.ApiError){int code=((WarehouseApi.ApiError)e).status;if(code==401)return "Нужен повторный вход · сканы сохранены";if(code==403)return "Доступ отключён · сканы сохранены";return e.getMessage();}return "Нет связи · сканы сохранены на ТСД";}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private GradientDrawable panel(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));return d;}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(TEXT);t.setTextSize(size);t.setPadding(0,dp(6),0,dp(6));return t;}
